def transform(grid):
    h, w = len(grid), len(grid[0])
    a = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            color = a[r][c]
            if color == 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and a[ny][nx] == color:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            comps.append((color, cells))

    # Move each object upward until blocked, repeatedly allowing objects below
    # to rise after the objects above them have moved.
    while True:
        moved = False
        comps.sort(key=lambda item: min(r for r, _ in item[1]))
        for color, cells in comps:
            if color == 2:
                continue
            positions = set(cells)
            if all(r > 0 and (r - 1, c) in positions or
                   (r > 0 and a[r - 1][c] == 0)
                   for r, c in cells):
                for r, c in cells:
                    a[r][c] = 0
                cells[:] = [(r - 1, c) for r, c in cells]
                for r, c in cells:
                    a[r][c] = color
                moved = True
        if not moved:
            break
    return a
